INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(52511, 'Ezekiel 12:27', 'Ezekiel', 12, 27, '«ای فاني انسانه، اسراییلیان فکر کوي چې ستا رویاګانې او پېشګویانې ډېر وروسته رښتیا کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel12_verse_27.mp3', '', 1761754199, 1761754199),
(52512, 'Ezekiel 12:28', 'Ezekiel', 12, 28, 'نو هغوی ته ووایه چې زه څښتن تعالی داسې وایم: ‹زما په کلام کې به نور کوم ځنډ نه رامنځته کیږي. څه چې ما وویل، نو هغه به خامخا کیږي. ما څښتن داسې وویل!›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel12_verse_28.mp3', '', 1761754199, 1761754199),
(52513, 'Jeremiah 49:1', 'Jeremiah', 49, 1, 'د عمونيانو په حقله مالِک خُدائ فرمائى چې، ”آيا د بنى اِسرائيلو څوک اولاد نشته؟ او د هغوئ څوک وارث نشته؟ نو بيا ولې د مولک بُت تابعدارى کوونکو د جاد په مال حال قبضه کړې ده او د هغوئ په ښارونو کښې اوسيږى؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_1.mp3', '', 1761754199, 1761754199),
(52514, 'Jeremiah 49:2', 'Jeremiah', 49, 2, 'مالِک خُدائ فرمائى، ”خو هغه ورځې راروانې دى کله چې زۀ به د عمونيانو د ربه د ښار خلاف د جنګ آواز وکړم. دا ښار به د تباهۍ نه د خاورو يو ډېرے جوړ شى، او د خوا او شا کلى به يې وسوزولے شى. نو بيا به بنى اِسرائيل هغه کسان وشړى چا چې دوئ شړلى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_2.mp3', '', 1761754199, 1761754199),
(52515, 'Jeremiah 49:3', 'Jeremiah', 49, 3, 'اے د حسبون ښځو، وژاړئ، ځکه چې د عى ښار تباه شو. اے د ربه ښځو، وير وکړئ. د ټاټ جامې واغوندئ او ماتم وکړئ. اخوا ديخوا سرګردانه وزغلئ، ځکه چې د مولک بُت به سره د خپلو اِمامانو او خادِمانو جلاوطن کړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_3.mp3', '', 1761754199, 1761754199),
(52516, 'Jeremiah 49:4', 'Jeremiah', 49, 4, 'تاسو ولې په خپل لوئ طاقت باندې فخر او لافې کوئ؟ ستاسو مال دولت به کم کړے شى، اے عمونه. چې د سرکشه جينۍ په شان په خپل مال دولت باندې يقين کوئ او داسې وايئ، په چا کښې جرأت شته چې په مونږ باندې حمله وکړى؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_4.mp3', '', 1761754199, 1761754199),
(52517, 'Jeremiah 49:5', 'Jeremiah', 49, 5, 'مالِک خُدائ ربُ الافواج فرمائى چې، ”ګورئ، زۀ به ستاسو د هرې خوا نه په تاسو باندې يره او وحشت راولم. او ستاسو هر يو کس به د مُلک نه وشړلے شى، او هيڅ څوک به هم دا مفروران يو ځائ ته راجمع نۀ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_5.mp3', '', 1761754199, 1761754199),
(52518, 'Jeremiah 49:6', 'Jeremiah', 49, 6, 'خو وروستو به زۀ عمونيان يو ځل بيا بحال کړم. دا د مالِک خُدائ فرمان دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_6.mp3', '', 1761754199, 1761754199),
(52519, 'Jeremiah 49:7', 'Jeremiah', 49, 7, 'د ادوميانو په حقله مالِک خُدائ ربُ الافواج داسې فرمائى چې، ”ولې په تيمان کښې نور حکمت او عقل نشته څۀ؟ آيا هوښياران ورته صحيح مشوره نۀ شى ورکولے څۀ؟ ولې د هغوئ عقل خوړلے شوے دے څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_7.mp3', '', 1761754199, 1761754199),
(52520, 'Jeremiah 49:8', 'Jeremiah', 49, 8, 'اے د ددان خلقو، واپس شئ او وتښتئ، او په غارونو کښې خپل ځان پټ کړئ، ځکه چې زۀ په عِيسو افت نازلوم نو په دغه وخت کښې به زۀ هغۀ ته هم سزا ورکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_8.mp3', '', 1761754199, 1761754199),
(52521, 'Jeremiah 49:9', 'Jeremiah', 49, 9, 'هغوئ څوک چې انګور راټولوى لږ څۀ غريبانانو ته پرېږدى. کۀ چرې په شپه کښې ورباندې غلۀ راشى، نو هغوئ به ورنه هر څۀ نۀ جارُو کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_9.mp3', '', 1761754199, 1761754199),
(52522, 'Jeremiah 49:10', 'Jeremiah', 49, 10, 'خو زۀ به د عِيسو نه هر څۀ جارُو کړم او د هغۀ پټ ځايونه به ښکاره کړم، نو هغه به يو ځائ هم خپل ځان پټولے نۀ شى. د هغۀ ماشومان، خپلوان، او ګاونډيان به تباه کړے شى، او هغه به نور په دُنيا کښې ژوندى پاتې نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_10.mp3', '', 1761754199, 1761754199),
(52523, 'Jeremiah 49:11', 'Jeremiah', 49, 11, 'خو زۀ به ستاسو د يتيمانو خيال ساتم او ستاسو کونډې دې هم په ما د مدد دپاره باور وکړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_11.mp3', '', 1761754199, 1761754199),
(52524, 'Jeremiah 49:12', 'Jeremiah', 49, 12, 'مالِک خُدائ فرمائى چې، ”کۀ چرې بې‌ګناه خلقو ته سزا ملاويږى، نو بيا به تاسو د څومره سزا لائق يئ. تاسو به بې‌سزا پاتې نۀ شئ. نو تاسو به ضرور د غضب د دې پيالۍ نه خوند واخلئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_12.mp3', '', 1761754199, 1761754199),
(52525, 'Jeremiah 49:13', 'Jeremiah', 49, 13, 'مالِک خُدائ فرمائى چې، ”زۀ په خپل ذات قسم خورم چې، د بُصره ښار به تباه شى او د خاورو ډېرے به جوړ شى او د ټولو خلقو دپاره به د وحشت، سپکوالى او د لعنت مثال وګرځى، او د هغۀ ټول ښارونه به د تل دپاره تباه او برباد شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_13.mp3', '', 1761754199, 1761754199),
(52526, 'Jeremiah 49:14', 'Jeremiah', 49, 14, 'ما د مالِک خُدائ له طرفه پېغام واورېدو، يو قاصد قومونو ته ولېږلے شو چې هغوئ ته ووائى چې، ”د ادوم په خلاف لښکر راجمع کړئ او د جنګ دپاره تيارى وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_14.mp3', '', 1761754199, 1761754199),
(52527, 'Jeremiah 49:15', 'Jeremiah', 49, 15, 'مالِک خُدائ ادوميانو ته فرمائى چې، اوس به زۀ تا د نورو قومونو په مينځ کښې کمزورے کړم. او ټول به تا ته په سپکه سترګه ګورى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_15.mp3', '', 1761754199, 1761754199),
(52528, 'Jeremiah 49:16', 'Jeremiah', 49, 16, 'ستا خپل دهشت او کوم کبر چې ستا په زړۀ کښې وو تۀ دوکه کړې، تاسو څوک چې د ګټانو په درزونو کښې اوسېږئ، او د غرونو اوچتې څوکې ستا په قبضه کښې دى. کۀ څۀ هم چې تۀ د باز په شان په اوچتو ځايونو کښې خپلې جالې جوړې کړې نو د هلته نه به زۀ تا لاندې راکوز کړم. دا د مالِک خُدائ فرمان دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_16.mp3', '', 1761754199, 1761754199),
(52529, 'Jeremiah 49:17', 'Jeremiah', 49, 17, 'ادوم به د خلقو دپاره د يرې مثال وګرځى، او څوک هم چې په دې لار تېريږى د هغوئ د ټولو افتونو پورې به حق حېران شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_17.mp3', '', 1761754199, 1761754199),
(52530, 'Jeremiah 49:18', 'Jeremiah', 49, 18, 'لکه څنګه چې سدوم او عموره، او د دې نه ګېرچاپېره ښارونو باندې تباهى راغلې وه، نو ادوم به هم هغه شان تباه شى، هلته به هيڅ څوک نۀ ژوند کوى او نۀ به اوسيږى. مالِک خُدائ داسې فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_18.mp3', '', 1761754199, 1761754199),
(52531, 'Jeremiah 49:19', 'Jeremiah', 49, 19, 'لکه څنګه چې يو زمرے د اُردن د جاړو بوټو نه د څرن زمکې ته راځى او په ګډو ورټوپ کوى، نو دغه شان به زۀ ادوميان د هغوئ د خپل مُلک نه وشړم، او زۀ به د خپلې خوښې مشر په کښې مقرر کړم. نو هغه به په دوئ حکومت وکړى. څوک زما په شان کېدلے شى؟ او يو مشر به هم زما خلاف ونۀ دريږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_19.mp3', '', 1761754199, 1761754199),
(52532, 'Jeremiah 49:20', 'Jeremiah', 49, 20, 'نو بيا هغې منصوبې ته غوږ شه کومه چې مالِک خُدائ د ادوم په خلاف جوړه کړې ده، او څۀ چې هغه د تيمان د خلقو سره کول غواړى. د هغوئ د رمې نه به واړۀ ګډورى راکاږى او هغه به په پوره توګه د هغوئ د څرن ځائ د دوئ په وجه وران کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_20.mp3', '', 1761754199, 1761754199),
(52533, 'Jeremiah 49:21', 'Jeremiah', 49, 21, 'د ادوم د راغورزېدو په آواز به زمکه ټوله په لړزان شى، او د هغوئ د چغو او سورو آواز به د بحرِقُلزمه پورې اورېدلے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_21.mp3', '', 1761754199, 1761754199),
(52534, 'Jeremiah 49:22', 'Jeremiah', 49, 22, 'ګورئ، دشمن لکه د باز په شان راغوټه شوے دے، او خپل وزرونه يې په بُصره باندې خوارۀ کړى دى، تر دې چې په هغه ورځ به د ادوم د تکړه فوجيانو زړۀ داسې په تکليف او يره کښې وى لکه چې د يوې ښځې زړۀ په لنګون کښې وى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_22.mp3', '', 1761754199, 1761754199),
(52535, 'Jeremiah 49:23', 'Jeremiah', 49, 23, 'مالِک خُدائ د دمشق په حقله دا پېغام ورکړو چې، ”د حمات او ارفاد ښارونه د يرې نه اوبۀ شول، ځکه چې هغوئ د خپل ځان د تباهۍ پېغام واورېدو. د هغوئ زړونه داسې بې‌سکونه شول لکه څنګه چې د سمندر چپې نا آرامه او بې‌سکونه وى او هيڅ سکون ورته نۀ ملاويږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_23.mp3', '', 1761754199, 1761754199),
(52536, 'Jeremiah 49:24', 'Jeremiah', 49, 24, 'د دمشق ښاريه د هغې ښځې په شان ده چې بې‌همته شوه، او د هغې ټول خلق وتښتېدل. يرې، وارخطايۍ، او درد هغه رانيولې ده لکه څنګه چې يوه ښځه د لنګون په وخت کښې نيولې وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_24.mp3', '', 1761754199, 1761754199),
(52537, 'Jeremiah 49:25', 'Jeremiah', 49, 25, 'دا مشهور ښار به څومره وران ويجاړ وى، کوم ښار چې په يو وخت کښې د خوشحالۍ ډک وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_25.mp3', '', 1761754199, 1761754199),
(52538, 'Jeremiah 49:26', 'Jeremiah', 49, 26, 'مالِک خُدائ ربُ الافواج فرمائى چې، د هغۀ ځوانان به په کوڅو کښې راپرېوځى او قتل به شى، او د هغوئ فوجيان به په هغه ورځ ټول ختم کړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_26.mp3', '', 1761754199, 1761754199),
(52539, 'Jeremiah 49:27', 'Jeremiah', 49, 27, 'زۀ به د دمشق په دېوالونو باندې اور ولګوم، او تر دې چې دا به د بِن‌حدد محلونه وسوزوى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_27.mp3', '', 1761754199, 1761754199),
(52540, 'Jeremiah 49:28', 'Jeremiah', 49, 28, 'د قيدار او د حاضور د علاقې په حقله کوم چې د بابل بادشاه نبوکدنضر ورباندې حمله وکړه، مالِک خُدائ فرمائى چې، ”راپاڅئ او په قيدار باندې حمله وکړئ او د مشرق اوسېدونکى تباه کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_28.mp3', '', 1761754199, 1761754199),
(52541, 'Jeremiah 49:29', 'Jeremiah', 49, 29, 'د هغوئ خېمې او رمې به قبضه کړے شى، د هغوئ د سر سورے به ترې نه سره د سامانه او اوښانو واخستلے شى. او خلق به د هرې خوا نه چغې سورې وهى. او هر چرته به يره خوره شوې وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_29.mp3', '', 1761754199, 1761754199),
(52542, 'Jeremiah 49:30', 'Jeremiah', 49, 30, 'مالِک خُدائ فرمائى چې، اے د حاضور خلقو په منډه وتښتئ. او خپل ځانونه په ژورو غارونو کښې پټ کړئ. ځکه چې د بابل بادشاه نبوکدنضر ستا خلاف منصوبه تياره کړې ده. او ستاسو د تباهۍ تيارے کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_30.mp3', '', 1761754199, 1761754199),
(52543, 'Jeremiah 49:31', 'Jeremiah', 49, 31, 'مالِک خُدائ فرمائى، راپاڅه او په هغه ښارونو باندې حمله وکړه څوک چې په آرام او سکون کښې ژوند کوى. د چا چې نۀ دروازې شته او نۀ دېوالونه او يواځې اوسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_31.mp3', '', 1761754199, 1761754199),
(52544, 'Jeremiah 49:32', 'Jeremiah', 49, 32, 'د هغوئ اوښان تالا کړه او د هغوئ رَمې لوټ کړه. او زۀ به هغوئ څوک چې په دشتو او ميرو کښې اوسيږى د هوا په مخکښې خوارۀ کړم او د هرې خوا نه به پرې افت نازل کړم. دا د مالِک خُدائ فرمان دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_32.mp3', '', 1761754199, 1761754199),
(52545, 'Jeremiah 49:33', 'Jeremiah', 49, 33, 'حاضور به د ګيدړانو د اوسېدو ځائ شى او د همېشه دپاره به وران او شاړ پروت وى. هيڅ څوک به هلته نۀ ژوند کوى او نۀ به اوسيږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_33.mp3', '', 1761754199, 1761754199),
(52546, 'Jeremiah 49:34', 'Jeremiah', 49, 34, 'دا د مالِک خُدائ هغه پېغام دے چې په يرمياه نبى باندې د عيلام په حقله د يهوداه د بادشاه صدقياه د بادشاهۍ په وړومبو ورځو کښې نازل شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_34.mp3', '', 1761754199, 1761754199),
(52547, 'Jeremiah 49:35', 'Jeremiah', 49, 35, 'مالِک خُدائ ربُ الافواج وفرمائيل چې، ”زۀ به د عيلام ليندې چلوونکى ووژنم، کوم چې د هغوئ د زور او طاقت اُميد دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_35.mp3', '', 1761754199, 1761754199),
(52548, 'Jeremiah 49:36', 'Jeremiah', 49, 36, 'زۀ به د آسمانونو د څلورو خوا نه په هغوئ باندې څلور بادونه راولم او هغوئ به ورته تس نس کړم، او داسې يو قوم او مُلک به نۀ وى چې د عيلام خلق ورته په جلاوطنۍ لاړ نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_36.mp3', '', 1761754199, 1761754199),
(52549, 'Jeremiah 49:37', 'Jeremiah', 49, 37, 'زۀ به د عيلام د خلقو په زړۀ کښې د هغوئ د دشمنانو يره واچوم. څوک چې د هغوئ مرګ پسې ګرځى، زۀ به په هغوئ افت نازل کړم او تر دې چې خپل خطرناک قهر او غضب به پرې راولم. دا د مالِک خُدائ فرمان دے. زۀ به هغوئ ته فوجيان ورولېږم چې دوئ راټينګ کړى تر دې چې ټول تباه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_37.mp3', '', 1761754199, 1761754199),
(52550, 'Jeremiah 49:38', 'Jeremiah', 49, 38, 'زۀ به خپل تخت په عيلام کښې قائم کړم، او د هغې بادشاه او آفسران به هلاک کړم. دا د مالِک خُدائ فرمان دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_38.mp3', '', 1761754199, 1761754199),
(52551, 'Jeremiah 49:39', 'Jeremiah', 49, 39, 'خو زۀ به په آئنده کښې د عيلام خلق بحال کړم. دا د مالِک خُدائ فرمان دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah49_verse_39.mp3', '', 1761754199, 1761754199),
(52552, 'Proverbs 28:1', 'Proverbs', 28, 1, 'بدکاران تښتي که څوک ورپسې روان هم نه وي خو نېکان د زمري په شان زړور وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_1.mp3', '', 1761754199, 1761754199),
(52553, 'Proverbs 28:2', 'Proverbs', 28, 2, 'په کوم وطن کې چې ګډوډي وي نو واکداران یې ډېر وي خو پوه او هوښیار مشران د دولت نظام ټینګ ساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_2.mp3', '', 1761754199, 1761754199),
(52554, 'Proverbs 28:3', 'Proverbs', 28, 3, 'کوم غریب واکدار چې په خوارانو ظلم کوي د هغه تېز باران په شان دی چې ټول فصل تباه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_3.mp3', '', 1761754199, 1761754199),
(52555, 'Proverbs 28:4', 'Proverbs', 28, 4, 'څوک چې له قانون نه سرغړونه کوي نو د بدکارانو ستاینه کوي خو څوک چې د قانون تابعداري کوي نو د بدکارانو مخالفت کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_4.mp3', '', 1761754199, 1761754199),
(52556, 'Proverbs 28:5', 'Proverbs', 28, 5, 'بدکاران په انصاف او عدالت نه پوهیږي خو څوک چې د څښتن لټون کوي هغوی په هرڅه ښه پوهیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_5.mp3', '', 1761754199, 1761754199),
(52557, 'Proverbs 28:6', 'Proverbs', 28, 6, 'هغه غریب چې خپل ژوند په صداقت تېروي له هغه شتمن نه ښه دی چې د منافقت په لار روان وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_6.mp3', '', 1761754199, 1761754199),
(52558, 'Proverbs 28:7', 'Proverbs', 28, 7, 'هوښیار زوی په قانون باندې عمل کوي خو د بد‌اخلاقانو ملګری خپل پلار سپکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_7.mp3', '', 1761754199, 1761754199),
(52559, 'Proverbs 28:8', 'Proverbs', 28, 8, 'څوک چې له غریبانو نه سود اخلي او خپله شتمني زیاتوي نو اخر به د هغوی مال د هغه چا شي چې په مسکینانو رحم کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_8.mp3', '', 1761754199, 1761754199),
(52560, 'Proverbs 28:9', 'Proverbs', 28, 9, 'څوک چې له قانون نه سرغړونه کوي نو څښتن د هغه له دعا نه کرکه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_9.mp3', '', 1761754199, 1761754199),
(52561, 'Proverbs 28:10', 'Proverbs', 28, 10, 'څوک چې صادقان بې‌لارې کوي او هغوی ته کنده کیندي نو په خپله به په کې راوغورځیږي خو د پاک زړه خاوندان به ښه میراث تر‌لاسه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_10.mp3', '', 1761754199, 1761754199),
(52562, 'Proverbs 28:11', 'Proverbs', 28, 11, 'شتمن سړی خپل ځان د حکمت خاوند ګڼي خو غریب عقلمن د هغه د زړه د تل نه خبر وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_11.mp3', '', 1761754199, 1761754199),
(52563, 'Proverbs 28:12', 'Proverbs', 28, 12, 'کله چې نېکان بریالي کیږي نو ټول خلک خوشحالیږي خو کله چې بدکاران واک ته رسیږي نو خلک ترې پټیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_12.mp3', '', 1761754199, 1761754199),
(52564, 'Proverbs 28:13', 'Proverbs', 28, 13, 'څوک چې خپله ګناه پټوي او په هغې پرده اچوي نو بریالی به نه شي خو څوک چې په خپلو ګناهونو اقرار کوي او لاس ترې اخلي نو په هغه به رحم وشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_13.mp3', '', 1761754199, 1761754199),
(52565, 'Proverbs 28:14', 'Proverbs', 28, 14, 'بختور دی هغه څوک چې هر وخت له څښتن څخه وېریږي خو څوک چې خپل زړه سخت کړي په بلا اخته کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_14.mp3', '', 1761754199, 1761754199),
(52566, 'Proverbs 28:15', 'Proverbs', 28, 15, 'بدکاره انسان چې په خوارانو حکومت کوي د غړمبېدونکي زمري یا د اېږې په شان چې ناڅاپه یرغل کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_15.mp3', '', 1761754199, 1761754199),
(52567, 'Proverbs 28:16', 'Proverbs', 28, 16, 'ناپوهه پاچا په خپلو خلکو ډېر ظلم کوي څوک چې د ناروا ګټې نه کرکه کوي تل خپل عمر اوږدوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_16.mp3', '', 1761754199, 1761754199),
(52568, 'Proverbs 28:17', 'Proverbs', 28, 17, 'که چا خپل لاسونه د بل په وینو سره کړي وي نو د مرګ تر کندې پورې به سرګردانه وي او هېڅوک دې د هغه سره مرسته نه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_17.mp3', '', 1761754199, 1761754199),
(52569, 'Proverbs 28:18', 'Proverbs', 28, 18, 'څوک چې خپل ژوند په صداقت تېروي هغه به وژغورل شي خو څوک چې منافقت کوي نو ناڅاپه به راوغورځول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_18.mp3', '', 1761754199, 1761754199),
(52570, 'Proverbs 28:19', 'Proverbs', 28, 19, 'څوک چې په خپله ځمکه کې کار کوي په ګېډه به موړ شي خو څوک چې د ورځې خوبونه کوي نو سخته غریبي به پرې راشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_19.mp3', '', 1761754199, 1761754199),
(52571, 'Proverbs 28:20', 'Proverbs', 28, 20, 'صادق انسان ته به ډېر زیات برکتونه ورکړل شي خو څوک چې ډېر زر شتمن کېدل غواړي نو بې‌سزا به پاتې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_20.mp3', '', 1761754199, 1761754199),
(52572, 'Proverbs 28:21', 'Proverbs', 28, 21, 'دا ښه کار نه دی چې د چا طرفداري وشي حتی یو سړی د یوې مړۍ ډوډۍ دپاره هم بې‌انصافي کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_21.mp3', '', 1761754199, 1761754199),
(52573, 'Proverbs 28:22', 'Proverbs', 28, 22, 'شوم سړی هڅه کوي چې زر شتمن شي خو په دې نه پوهیږي چې نېستي د هغه انتظار کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_22.mp3', '', 1761754199, 1761754199),
(52574, 'Proverbs 28:23', 'Proverbs', 28, 23, 'څوک چې بل اصلاح کوي نو په اخر کې به عزتمن شي له هغه چا نه چې ډېره غوړه‌مالي کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_23.mp3', '', 1761754199, 1761754199),
(52575, 'Proverbs 28:24', 'Proverbs', 28, 24, 'څوک چې د خپل مور او پلار مال په زور اخلي او وایي چې دا کومه ګناه نه ده نو د ورانکارو سره ملګرتیا کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_24.mp3', '', 1761754199, 1761754199),
(52576, 'Proverbs 28:25', 'Proverbs', 28, 25, 'د وږیو سترګو خاوند جنګ جګړې جوړوي خو څوک چې په څښتن باور کوي نو اباد به شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_25.mp3', '', 1761754199, 1761754199),
(52577, 'Proverbs 28:26', 'Proverbs', 28, 26, 'څوک چې په خپل ځان ډاډه وي هغه کم‌عقل دی خو څوک چې د حکمت په لار روان وي خلاصون به ومومي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_26.mp3', '', 1761754199, 1761754199),
(52578, 'Proverbs 28:27', 'Proverbs', 28, 27, 'څوک چې د مسکینانو سره مرسته کوي نو له نېستۍ سره به مخ نه شي خو څوک چې پرې سترګې پټوي نو لعنتونه به ورباندې ووریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_27.mp3', '', 1761754199, 1761754199),
(52579, 'Proverbs 28:28', 'Proverbs', 28, 28, 'کله چې بدکاران واک ته رسیږي نو خلک ترې پټیږي خو کله چې هغوی بربادیږي نو نېکان ابادیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs28_verse_28.mp3', '', 1761754199, 1761754199),
(52580, 'Jeremiah 8:1', 'Jeremiah', 8, 1, 'مالِک خُدائ فرمائى چې، ”په هغه وخت کښې به دشمن د بادشاهانو او د يهوداه د آفسرانو، د اِمامانو او د پېغمبرانو او د يروشلم د نورو خلقو هډُوکى د قبرونو نه بهر راوباسى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_1.mp3', '', 1761754199, 1761754199),
(52581, 'Jeremiah 8:2', 'Jeremiah', 8, 2, 'او د زمکې په مخ به يې خوارۀ وارۀ کړى او هلته به د هغه چا په وړاندې يعنې د نمر، سپوږمۍ او ستورو مخې ته پراتۀ وى د چا چې هغوئ عبادت کولو، ځکه چې هغوئ د دې څيزونو خِدمت کولو، او دې پسې روان وُو، او دې ته يې سجده کوله. د هغوئ هډُوکى به دوباره په خپلو کښې رايوځائ نۀ شى او نۀ به ښخ کړے شى بلکې د ډيران په شان به پراتۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_2.mp3', '', 1761754199, 1761754199),
(52582, 'Jeremiah 8:3', 'Jeremiah', 8, 3, 'او هر چرته چې د دې بدعمله قوم ژوندى کسان کوم چې ما خوارۀ وارۀ کړى دى اوسيږى، نو هغوئ به د ژوند نه په مرګ باندې خوشحاله وى.“ مالِک خُدائ ربُ الافواج خُدائ دا وفرمائيل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_3.mp3', '', 1761754199, 1761754199),
(52583, 'Jeremiah 8:4', 'Jeremiah', 8, 4, '”هغوئ ته ووايه چې مالِک خُدائ داسې فرمائى، هرکله چې څوک راپرېوځى، نو هغوئ بيا نۀ راپاڅى څۀ؟ هرکله چې يو سړے په غلطه لار روان شى آيا هغه به بيا راواپس نۀ شى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_4.mp3', '', 1761754199, 1761754199),
(52584, 'Jeremiah 8:5', 'Jeremiah', 8, 5, 'نو بيا د يروشلم خلق د صحيح لارې نه ولې اوړېدلى دى؟ دوئ په دروغو او دوکه مارۍ کښې خپل ځان انغښتے دے او ما ته د واپس راتلو نه اِنکار کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_5.mp3', '', 1761754199, 1761754199),
(52585, 'Jeremiah 8:6', 'Jeremiah', 8, 6, 'ما هغوئ ته په غور سره غوږ ونيولو خو هغوئ حقيقت نۀ وئيلو. او څوک هم په خپلو بدو کارونو باندې توبه ګار نۀ وُو او چا هم دا نۀ وئيل چې، ”دا مې کوم غلط کار وکړو؟“ لکه څنګه چې آس د جنګ مېدان ته په منډه روان وى دغه شان دوئ هم هر يو په خپلو غلطو لارو په تېزۍ سره روان دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_6.mp3', '', 1761754199, 1761754199),
(52586, 'Jeremiah 8:7', 'Jeremiah', 8, 7, 'تر دې چې مختلف مارغان لکه ډينګان، ګوګوشتکې، طوطاګرکى او زاڼى هم په دې پوهيږى چې اوس موسم بدل شو او راواپس کيږى. خو زما غوره شوے قوم زما د قانون نه ناخبره دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_7.mp3', '', 1761754199, 1761754199),
(52587, 'Jeremiah 8:8', 'Jeremiah', 8, 8, 'تاسو څنګه دا وايئ چې، مونږ ټول هوښياران يُو ځکه چې مونږ سره د مالِک خُدائ شريعت موجود دے؟ او حال دا چې د شريعت عالمانو په خپلو دروغو سره اصلى شريعت بدل کړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_8.mp3', '', 1761754199, 1761754199),
(52588, 'Jeremiah 8:9', 'Jeremiah', 8, 9, 'ګورئ دغه هوښياران به وشرميږى او په خپل کم عقلتوب کښې به راګېر شى. ځکه چې هغوئ د مالِک خُدائ کلام رد کړو نو بيا د دوئ هوښيارتيا چرته لاړه؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_9.mp3', '', 1761754199, 1761754199),
(52589, 'Jeremiah 8:10', 'Jeremiah', 8, 10, 'نو په دې وجه به زۀ د هغوئ ښځې پردو سړو ته حواله کړم او زمکه او جائيداد به يې هم نورو خلقو له ورکړم. ځکه چې د ماشومانو نه واخله تر بوډاګانو پورې هر يو د ناجائزه ګټې په لالچ کښې دى، د ‎پېغمبر نه واخله تر اِمام پورې ټول دوکه ماران دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_10.mp3', '', 1761754199, 1761754199),
(52590, 'Jeremiah 8:11', 'Jeremiah', 8, 11, 'هغوئ زما د خلقو د سختو زخمونو عرضى علاج کوى. او کله چې خير نۀ وى نو هغوئ وائى چې، خير دے، خير به شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_11.mp3', '', 1761754199, 1761754199),
(52591, 'Jeremiah 8:12', 'Jeremiah', 8, 12, 'آيا هغوئ په خپل دې پليت عمل شرمېدل څۀ؟ نه، هغوئ بلکل شرم نۀ لرلو، هغوئ په دې هم نۀ پوهيږى چې شرم څۀ ته وائى. دوئ به د تباه شوو په مينځ کښې حساب شى. زۀ به دوئ هم ختم کړم کله چې زۀ هغوئ له سزا ورکوم،“ مالِک خُدائ فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_12.mp3', '', 1761754199, 1761754199),
(52592, 'Jeremiah 8:13', 'Jeremiah', 8, 13, '”زۀ به د دوئ پوره فصل تباه کړم. د انګورو په بوټى کښې به يوه دانه هم پاتې نۀ شى، او نۀ به اينځر د اينځر په ونه کښې وليدلے شى، د دوئ پاڼې به اوچې شى. او هر څۀ چې ما دوئ له ورکړى دى هغه به ترې نه واپس واخلم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_13.mp3', '', 1761754199, 1761754199),
(52593, 'Jeremiah 8:14', 'Jeremiah', 8, 14, 'نو بيا به دوئ وائى چې مونږ ولې دلته په آرام سره ناست يُو؟ راځئ چې قلعه بند ښارونو ته وتښتو چې هلته کښې مړۀ شُو، ځکه چې مالِک خُدائ زمونږ خُدائ دا تباهى راباندې راوستې ده او د زهرو ډک جام يې مونږ ته څښلو دپاره راکړے دے. ځکه چې مونږ د مالِک خُدائ خلاف ګناه کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_14.mp3', '', 1761754199, 1761754199),
(52594, 'Jeremiah 8:15', 'Jeremiah', 8, 15, 'مونږ د امن په طمع وُو، خو مونږ هيڅ خير ونۀ ليدلو. مونږ د شفا حاصلولو اُميد کولو، بلکې د هغې په ځائ په مونږ يره راغله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_15.mp3', '', 1761754199, 1761754199),
(52595, 'Jeremiah 8:16', 'Jeremiah', 8, 16, 'واورئ. زمونږ د دشمن د آسونو شڼېدل د دان د ښار نه اورېدلے کيږى. او د هغوئ د آسونو د هڼېدلو نه ټوله زمکه په لړزېدو ده. هغوئ د دې دپاره راغلى دى چې دا مُلک او هر څۀ چې په کښې دى تباه کړى، ښارونه او هر څوک چې په کښې اوسيږى تېر کړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_16.mp3', '', 1761754199, 1761754199),
(52596, 'Jeremiah 8:17', 'Jeremiah', 8, 17, 'مالِک خُدائ فرمائى، ”زۀ به ستاسو خلاف زهريله ماران درولېږم چې هيڅ قسم منتر به په هغې اثر نۀ کوى او هغه به تاسو وچيچى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_17.mp3', '', 1761754199, 1761754199),
(52597, 'Jeremiah 8:18', 'Jeremiah', 8, 18, 'نو بيا ما ووئيل چې خوشحالى زما نه لاړه او زما د خفګان علاج نشته، او دننه زړۀ مې بې‌هوشه دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_18.mp3', '', 1761754199, 1761754199),
(52598, 'Jeremiah 8:19', 'Jeremiah', 8, 19, 'زما د خلقو ژړا ته غوږ ونيسئ چې په ټول مُلک کښې اورېدلے کيږى، هغوئ تپوس کوى وائى چې، ”آيا مالِک خُدائ صيون پرېښودے دے څۀ؟ آيا د هغوئ بادشاه نور دلته کښې نشته څۀ؟“ مالِک خُدائ ورته په جواب کښې فرمائى چې، ”تاسو ولې د هسې فضول او پردو بُتانو په عبادت زما قهر او غضب راوپارولو؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_19.mp3', '', 1761754199, 1761754199),
(52599, 'Jeremiah 8:20', 'Jeremiah', 8, 20, 'خلق چغې سورې وهى او ژاړى چې، ”اوړے تېر شو، فصل لو شو، خو مونږ لا بچ نۀ يُو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_20.mp3', '', 1761754199, 1761754199),
(52600, 'Jeremiah 8:21', 'Jeremiah', 8, 21, 'زۀ د خپلو خلقو د دردونو سره دردمند شوم. او په پرېشانۍ کښې راګېر شوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_21.mp3', '', 1761754199, 1761754199),
(52601, 'Jeremiah 8:22', 'Jeremiah', 8, 22, 'آيا په جِلعاد کښې مرهم نشته؟ آيا هلته طبيبان نشته څۀ؟ نو بيا ولې زما د قوم د زخمونو دپاره شفا نشته څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah8_verse_22.mp3', '', 1761754199, 1761754199),
(52602, 'Exodus 15:1', 'Exodus', 15, 1, 'بیا موسی او اسراییلیانو څښتن ته دا سندره وویله: زه به ووایم سندره د څښتن دپاره ځکه چې ویې موند بری د جلاله سره بحیرې ته یې اسونه ورګوزار کړل او سپاره د هغو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_1.mp3', '', 1761754199, 1761754199),
(52603, 'Exodus 15:2', 'Exodus', 15, 2, 'څښتن قوت دی زما او هغه څوک دی چې په هکله یې سندره وایم دا هغه څوک دی چې یې ژغورلی یم زه هغه دی خدای زما او زه به یې کړم ستاینه زما د پلار خدای دی او وبه وایم چې دی لوړ هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_2.mp3', '', 1761754199, 1761754199),
(52604, 'Exodus 15:3', 'Exodus', 15, 3, 'دی جنګیالی څښتن د هغه نوم دی څښتن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_3.mp3', '', 1761754199, 1761754199),
(52605, 'Exodus 15:4', 'Exodus', 15, 4, 'جنګي ګاډۍ او لښکرې د فرعون بحیرې ته ورګوزارې کړې هغه د فرعون ډېر ښه منصبداران سره بحیره کې ډوب شول', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_4.mp3', '', 1761754199, 1761754199),
(52606, 'Exodus 15:5', 'Exodus', 15, 5, 'هغوی لاندې کړل ژورې بحیرې هغوی ورسېدل تل ته لکه د تیږې په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_5.mp3', '', 1761754199, 1761754199),
(52607, 'Exodus 15:6', 'Exodus', 15, 6, 'ستا په ښي لاس کې ای څښتنه هیبتناکه زور موجود دی ستا ښي لاس ای څښتنه ټوټې ټوټې کوي دښمنان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_6.mp3', '', 1761754199, 1761754199),
(52608, 'Exodus 15:7', 'Exodus', 15, 7, 'په خپل لوی جلال سره ته له پښو غورځوې خپل دښمنان لمبه کیږي قهر ستا او سوځوي هغوی لکه د بوسو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_7.mp3', '', 1761754199, 1761754199),
(52609, 'Exodus 15:8', 'Exodus', 15, 8, 'تا بحیره پو کړه او اوبه ډېرۍ شوې ودرېدل کلک سېلابونه لکه دېوال په شان شوه جامده د بحیرې ډېره ژوره برخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_8.mp3', '', 1761754199, 1761754199),
(52610, 'Exodus 15:9', 'Exodus', 15, 9, 'دښمن وهلې لافې زه به تعقیب کړم هغوی او وبه رسېږم ورته وبه وېشم زه غنیمت د هغوی زه به موړ کړمه خپل ځان ورباندې زه به راوباسمه خپله توره او زه به تباه کړم هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus15_verse_9.mp3', '', 1761754199, 1761754199);